CREATE OR REPLACE FUNCTION public.begin_my_work_attachment_transfer(p_id uuid, p_recipient uuid, p_body text, p_job uuid, p_files jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare existing public.my_work_messages%rowtype; request jsonb; item jsonb; total bigint; actor public.app_users%rowtype;
BEGIN
  perform public.require_app_capability('messaging.write');
  select * into strict actor from public.app_users where user_id=auth.uid() and is_active;
  if p_id is null or p_recipient is null or p_recipient=auth.uid() then raise exception 'Choose another recipient.'; end if;
  request=jsonb_build_object('recipient',p_recipient,'body',btrim(p_body),'job',p_job,'files',p_files);
  -- Serializes concurrent calls even before the message row exists.
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
  select * into existing from public.my_work_messages where id=p_id for update;
  if found then
    if existing.sender_user_id<>auth.uid() or existing.upload_request is distinct from request then raise exception 'Transfer identity does not match.' using errcode='42501'; end if;
    if existing.delivery_status='draft' and existing.upload_state='active' then update public.my_work_messages set upload_touched_at=clock_timestamp() where id=p_id; end if;
    return;
  end if;
  if not exists(select 1 from public.app_users where user_id=p_recipient and is_active and (role<>'developer' or actor.role='admin')) then raise exception 'Recipient unavailable.'; end if;
  if p_body is null or length(btrim(p_body))>10000 then raise exception 'Message must contain at most 10000 characters.'; end if;
  if p_job is not null and not exists(select 1 from public.jobs where id=p_job) then raise exception 'Job unavailable.'; end if;
  if jsonb_typeof(p_files)<>'array' or jsonb_array_length(p_files)<1 or p_files is null then raise exception 'Attachments required.'; end if;
  select sum((x->>'size')::bigint) into total from jsonb_array_elements(p_files) x;
  if total is null or total>200000000 then raise exception 'Attachments exceed 200 MB/message.'; end if;
  if exists(select 1 from public.my_work_message_deletion_audit where deleted_message_id=p_id) then raise exception 'This message was permanently deleted.'; end if;
  insert into public.my_work_messages(id,sender_user_id,recipient_user_id,body,job_id,delivery_status,upload_request,upload_state,upload_touched_at)
  values(p_id,auth.uid(),p_recipient,btrim(p_body),p_job,'draft',request,'active',clock_timestamp());
  for item in select * from jsonb_array_elements(p_files) loop
    if (item->>'size') is null or (item->>'name') is null or (item->>'id') is null or (item->>'contentType') is null then raise exception 'Invalid file manifest.'; end if;
    insert into public.my_work_message_attachments(id,message_id,uploader_user_id,storage_path,original_filename,content_type,byte_size)
    values((item->>'id')::uuid,p_id,auth.uid(),p_id::text||'/'||(item->>'id')::uuid::text||'/file',item->>'name',item->>'contentType',(item->>'size')::bigint);
  end loop;
end;$function$

CREATE OR REPLACE FUNCTION public.finalize_my_work_inbox_message(p_message_id uuid, p_expected_attachment_count integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'storage'
AS $function$
declare m public.my_work_messages%rowtype; actor public.app_users%rowtype; n integer; total bigint;
BEGIN
  perform public.require_app_capability('messaging.write');
  select * into strict actor from public.app_users where user_id=auth.uid() and is_active;
  select * into strict m from public.my_work_messages where id=p_message_id and sender_user_id=auth.uid() for update;
  if m.upload_request is null then raise exception 'Refresh Messaging before sending attachments.'; end if;
  select count(*),sum(byte_size) into n,total from public.my_work_message_attachments where message_id=m.id;
  if p_expected_attachment_count is null or p_expected_attachment_count<1 or n<>p_expected_attachment_count or total>200000000 then raise exception 'Attachment manifest incomplete or too large.'; end if;
  if m.delivery_status='ready' then return; end if;
  if m.upload_state is distinct from 'active' then raise exception 'Transfer canceled.'; end if;
  if exists(select 1 from public.my_work_message_attachments a left join storage.objects o on o.bucket_id='my-work-inbox-attachments' and o.name=a.storage_path
    where a.message_id=m.id and (o.id is null or (o.metadata->>'size')::bigint is distinct from a.byte_size)) then raise exception 'Attachment bytes are incomplete.'; end if;
  update public.my_work_messages set delivery_status='ready',upload_state=null where id=m.id;
  insert into public.account_notifications(user_id,notification_key,notification_type,title,body,metadata)
  values(m.recipient_user_id,'inbox-message:'||m.id,'inbox_message',actor.display_name||' sent you a message','Open Inbox to read it.',jsonb_strip_nulls(jsonb_build_object('message_id',m.id,'conversation_user_id',actor.user_id,'job_id',m.job_id,'purpose','open-my-work-inbox')))
  on conflict(user_id,notification_key) do nothing;
end;$function$

CREATE OR REPLACE FUNCTION public.notify_job_update_account(p_user_id uuid, p_update job_updates, p_purpose text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  selected_job public.jobs%rowtype;
  notification_title text;
begin
  if p_user_id is null then return; end if;
  if p_purpose not in ('mention', 'assignment') then
    raise exception 'Invalid Job Update notification purpose.' using errcode = '22023';
  end if;
  if p_purpose = 'assignment' and p_user_id = auth.uid() then return; end if;
  if not exists (select 1 from public.app_users where user_id = p_user_id and is_active) then
    raise exception 'Job Update recipient must be an active TenOps user.' using errcode = '22023';
  end if;

  select * into selected_job from public.jobs where id = p_update.job_id;
  if not found then raise exception 'Production Job was not found.' using errcode = 'P0002'; end if;
  notification_title := case p_purpose
    when 'mention' then 'You were mentioned in a Job Update'
    else 'A Job Update was assigned to you'
  end;

  insert into public.account_notifications(
    user_id, notification_key, notification_type, title, body, metadata
  ) values (
    p_user_id,
    'job-update-' || p_purpose || ':' || p_update.id::text,
    'job_update_' || p_purpose,
    notification_title,
    coalesce(nullif(btrim(selected_job.job_number), '') || ' · ', '') || selected_job.name || E'\n' || left(p_update.body, 180),
    jsonb_build_object(
      'job_id', p_update.job_id,
      'update_id', p_update.id,
      'job_number', selected_job.job_number,
      'job_name', selected_job.name,
      'purpose', p_purpose
    )
  ) on conflict (user_id, notification_key) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_my_work_inbox_message(p_recipient_user_id uuid, p_body text, p_job_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare actor public.app_users%rowtype; recipient public.app_users%rowtype; selected_job public.jobs%rowtype; message_id uuid:=gen_random_uuid();
BEGIN
  perform public.require_app_capability('messaging.write');
  select * into strict actor from public.app_users where user_id=auth.uid() and is_active;
  if p_recipient_user_id=actor.user_id then raise exception 'Choose another TenOps user.' using errcode='22023'; end if;
  select * into strict recipient from public.app_users where user_id=p_recipient_user_id and is_active;
  if nullif(btrim(coalesce(p_body,'')),'') is null then raise exception 'Message is required.' using errcode='22023'; end if;
  if length(btrim(p_body))>10000 then raise exception 'Message is too long.' using errcode='22023'; end if;
  if p_job_id is not null then select * into strict selected_job from public.jobs where id=p_job_id; end if;
  insert into public.my_work_messages(id,sender_user_id,recipient_user_id,body,job_id)
  values(message_id,actor.user_id,recipient.user_id,btrim(p_body),p_job_id);
  insert into public.account_notifications(user_id,notification_key,notification_type,title,body,metadata)
  values(recipient.user_id,'inbox-message:'||message_id,'inbox_message',actor.display_name||' sent you a message','Open Inbox to read it.',
    jsonb_strip_nulls(jsonb_build_object('message_id',message_id,'conversation_user_id',actor.user_id,'job_id',p_job_id,'purpose','open-my-work-inbox')));
  return message_id;
end;$function$

CREATE OR REPLACE FUNCTION public.sync_job_update_mentions(p_update job_updates, p_mentioned_user_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  mentioned_user_id uuid;
begin
  if auth.uid() is null and coalesce(cardinality(p_mentioned_user_ids), 0) > 0 then
    raise exception 'Sign in to mention a TenOps user.' using errcode = '42501';
  end if;
  if exists (
    select 1 from unnest(coalesce(p_mentioned_user_ids, array[]::uuid[])) candidate(user_id)
    left join public.app_users users on users.user_id = candidate.user_id and users.is_active
    where users.user_id is null
  ) then
    raise exception 'Mentions may target active TenOps users only.' using errcode = '22023';
  end if;

  delete from public.job_update_mentions
  where job_update_id = p_update.id
    and not (user_id = any(coalesce(p_mentioned_user_ids, array[]::uuid[])));

  for mentioned_user_id in
    insert into public.job_update_mentions(job_update_id, user_id)
    select p_update.id, candidate.user_id
    from (select distinct unnest(coalesce(p_mentioned_user_ids, array[]::uuid[])) user_id) candidate
    on conflict do nothing
    returning user_id
  loop
    perform public.notify_job_update_account(mentioned_user_id, p_update, 'mention');
  end loop;
end;
$function$
